AOS.init({once:!0});const swiper=new Swiper(".swiper",{direction:"horizontal",loop:!1,autoHeight:!0});let buttons=Array.from(document.querySelectorAll(".menu_btn"));document.querySelectorAll(".menu_btn").forEach(e=>{e.addEventListener("click",e=>{document.querySelectorAll(".menu_btn").forEach(e=>{e.classList.remove("active")}),e.currentTarget.classList.add("active");var t=buttons.indexOf(e.currentTarget);swiper.slideTo(t)})}),swiper.on("slideChange",function(){buttons.forEach(e=>{e.classList.remove("active")}),buttons[swiper.activeIndex].classList.add("active"),console.log(swiper.activeIndex)});var logo=document.querySelector('img[src="/src/images/Estrella.png"]'),nav=document.querySelector(".nav_fixed");window.addEventListener("scroll",function(){logo.getBoundingClientRect().bottom<0?nav.classList.add("nav_on"):nav.classList.remove("nav_on")});